CREATE OR REPLACE PROCEDURE sp(
    para_Injured IN NUMBER,
    para_Country IN VARCHAR2,
    para_Height  IN BINARY_FLOAT,
    para_Name    IN VARCHAR2
)
AS
    rec_id NUMBER;
    rec_val VARCHAR2(4000);
    rec_killed NUMBER;
    v_fetched_count NUMBER := 0;
    v_killed_total NUMBER := 0;

    CURSOR cur IS
        SELECT Injured, Country, Killed
        FROM perpetrator
        WHERE Injured > para_Injured
        ORDER BY Perpetrator_ID ASC
        FETCH FIRST 10 ROWS ONLY;
BEGIN
    UPDATE perpetrator SET Country = 'init';
    DELETE FROM people WHERE Name IS NULL;

    OPEN cur;
    LOOP
        FETCH cur INTO rec_id, rec_val, rec_killed;
        EXIT WHEN cur%NOTFOUND;

        v_fetched_count := v_fetched_count + 1;
        v_killed_total := v_killed_total + NVL(rec_killed, 0);

        IF rec_id > 1000 THEN
            DELETE FROM perpetrator WHERE Injured = rec_id;
            DELETE FROM people WHERE Height = rec_id;
        ELSIF rec_id > 100 THEN
            UPDATE perpetrator SET Country = rec_val || '_updated' WHERE Injured = rec_id;
            UPDATE people SET Name = 'UPDATED_LOG' WHERE Height = rec_id;
        ELSE
            UPDATE perpetrator SET Country = rec_val || '_checked' WHERE Injured = rec_id;
            DELETE FROM people WHERE Height = rec_id;
        END IF;
    END LOOP;
    CLOSE cur;

    UPDATE perpetrator SET Country = 'finished';
    UPDATE people SET Name = 'finished_log';
    DELETE FROM perpetrator WHERE Country IS NULL;
    DELETE FROM people WHERE Name IS NULL;
    UPDATE perpetrator SET Country = 'final_pass';
    UPDATE people SET Name = 'final_pass_log';
    DELETE FROM perpetrator WHERE Country LIKE '%error%';
    DELETE FROM people WHERE Name LIKE '%error%';
    UPDATE perpetrator SET Country = para_Country;
    UPDATE people SET Name = para_Name;
    DELETE FROM perpetrator WHERE Injured = para_Injured;
    DELETE FROM people WHERE Height = para_Height;

    IF v_fetched_count > 0 THEN
        UPDATE perpetrator SET Country = 'processed' WHERE Injured > para_Injured;
    END IF;

    IF v_killed_total >= 50 THEN
        UPDATE perpetrator SET Country = 'mass_processed'
        WHERE Injured > para_Injured AND Killed >= 50;
    END IF;
END sp;
/

